import {pythonLink} from './python-links.mjs';
import {VERSION,STORAGE_KEY,STEPS,freshState,restoreState,allocate,DIAGNOSTIC,INSTRUMENTS,gradeQuestions,currentAssessment,chapterComplete,invalidateEvidence} from './model.mjs';

let state=freshState(),storageOK=true;
try{state=restoreState(localStorage.getItem(STORAGE_KEY));localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageOK=false;}
let page='start';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=id=>state.fields[id]??'';
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:2}).format(n);
function persist(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';updateNav();}
function announce(message){$('#announcement').textContent='';requestAnimationFrame(()=>$('#announcement').textContent=message);}
function mark(id){state.done[id]=true;persist();}
function updateNav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#navigation').innerHTML=STEPS.map(([id,title,min],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':String(i+1).padStart(2,'0')}</span><span>${title}<small>${min} min${state.done[id]?' · complete':''}</small></span></a>`).join('');$('#progress-label').textContent=`${n} of 7 steps complete`;$('#progress-percent').textContent=`${Math.round(n/7*100)}%`;$('#progress').value=n;$('#progress').textContent=`${n} of 7 steps complete`;}
function heading(eyebrow,title,lead){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p>`;}
function bottom(){const i=STEPS.findIndex(([id])=>id===page);return `<div class="bottom-nav">${i>0?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<span class="mini">No timer. Learn at your pace.</span>'}${i<STEPS.length-1?`<div><small>Up next</small><a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]} →</a></div>`:'<a href="#start">Back to chapter overview ↑</a>'}</div>`;}
function field(id,label,placeholder='',type='text'){return `<label class="field" for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}" data-save placeholder="${esc(placeholder)}">${esc(val(id))}</textarea>`:`<input type="${type}" id="${id}" data-save value="${esc(val(id))}" placeholder="${esc(placeholder)}">`}`;}
function choices(q,prefix=''){const name=prefix+q.id;return `<fieldset class="question"><legend>${esc(q.title)}</legend><div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="${name}" value="${i}" data-save ${String(val(name))===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div></fieldset>`;}
function confidence(id){return `<label class="field" for="${id}">How confident are you? <small>For reflection only. Confidence never changes your score.</small></label><select id="${id}" data-save><option value="">Choose if useful</option>${['Still unsure','Somewhat confident','Confident'].map(s=>`<option ${val(id)===s?'selected':''}>${s}</option>`).join('')}</select>`;}
function feedback(id,text,error=false){const el=$('#'+id);el.innerHTML=text;el.className=`feedback${error?' error':''}`;el.setAttribute('tabindex','-1');el.focus();announce(el.textContent);}
function go(id){location.hash=id;}
function savedCheck(id,label){return `<label class="option"><input type="checkbox" id="${id}" data-save ${val(id)?'checked':''}><span>${label}</span></label>`;}

const views={
start(){return `<div class="hero"><div class="hero-copy"><div class="eyebrow">CHAPTER 01 · THE STARTING POINT</div><h1>Start with<br>a good <em>question.</em></h1><p class="lead">Before the formulas and the code, learn to turn an investment idea into something you can actually investigate.</p><div class="pill-row"><span class="pill">Beginner friendly</span><span class="pill">About 3 hours</span><span class="pill">No installation</span></div><button data-action="begin">${state.done.start?'Continue learning':'Set up my workspace'} <span aria-hidden="true">↗</span></button></div><div class="hero-visual"><div class="visual-head"><span>FROM AN IDEA TO EVIDENCE</span><span class="visual-tag">ILLUSTRATION</span></div><svg class="plot" viewBox="0 0 350 160" role="img" aria-labelledby="plot-title plot-desc"><title id="plot-title">Two illustrative paths from a shared starting point</title><desc id="plot-desc">Two invented lines rise and fall differently. A comparison needs a stated question, a baseline and the same observation period. This is not investment data.</desc><g fill="none" stroke="#c9d5bf" stroke-width="1"><path d="M15 20H335M15 60H335M15 100H335M15 140H335"/></g><path d="M15 125L43 119L72 131L101 104L130 110L159 83L188 88L217 61L246 74L275 45L304 51L335 23" fill="none" stroke="#285947" stroke-width="3"/><path d="M15 125L43 126L72 117L101 119L130 97L159 101L188 80L217 89L246 84L275 71L304 78L335 61" fill="none" stroke="#82985f" stroke-width="2" stroke-dasharray="5 5"/><circle cx="335" cy="23" r="5" fill="#285947"/></svg><p class="chart-caption">A better-looking line is the beginning of a question.</p><div class="visual-rule"><span>?</span> Compared with what?</div></div></div><div class="section-line"><h2>Three things you'll leave with.</h2><span class="meta">SMALL STEPS. REAL REASONING.</span></div><div class="cards"><article class="card"><span class="card-number">01</span><h3>A map of the market</h3><p>Recognise cash, bonds, shares and funds—and the different claims they represent.</p></article><article class="card"><span class="card-number">02</span><h3>A fair comparison</h3><p>Choose a useful baseline and explore a hypothetical portfolio without risking money.</p></article><article class="card"><span class="card-number">03</span><h3>Your first research card</h3><p>Specify a rule, a benchmark, a period and the evidence that would change your mind.</p></article></div><section class="panel" id="setup-panel"><span class="badge">SETUP · 15 MINUTES</span><h2 style="margin-top:15px">Your browser is the workspace.</h2><ol class="step-list"><li><strong>Use a modern browser on a laptop, tablet or phone.</strong> A larger screen helps with tables. You need no prior coding, market account, software install or broker connection. The hosted preview may use its existing private access sign-in.</li><li><strong>Check input and saving.</strong> Type a short workspace label below. Avoid your full name or other personal information. Leave this step and return to confirm it remains.</li><li><strong>Choose your route.</strong> Everything has a table or text equivalent. <a href="chapter-guide.html">Open the printable text route</a> if JavaScript, saving or a screen layout causes difficulty.</li><li><strong>Make room to learn.</strong> Suggested total time is 180 minutes, with breaks whenever you want. There is no countdown or timed test. Timing is a design estimate awaiting learner trials.</li></ol>${field('workspace','Workspace label','For example: My first finance question')}<div class="callout"><strong>How saving works</strong><p>Your learning answers stay in this browser. Export a progress file before changing devices or clearing browser data. The file is a record for you; this version has no import or account sync.</p></div>${savedCheck('setupConfirmed','I can use the input above and know where to find Export and Privacy & reset.')}<div class="actions"><button data-action="setup">Confirm setup & continue →</button><button class="secondary" data-action="export">Export a test progress file</button></div><div id="setup-feedback" class="feedback" role="status"></div></section><details class="hint"><summary>What counts as completing this chapter?</summary><p>Complete setup, submit the ungraded diagnostic, correct the four instrument classifications, explain the worked comparison, finish two lab scenarios with a hand check, pass the independent check and save a research card with a feedback revision. You can visit any step at any time. This is formative self-study, not an accredited or proctored exam.</p></details>`;},
readiness(){return heading('STEP 02 · 30 MINUTES','Find your<br>starting point.','Three short questions help you choose useful practice. This check is ungraded; a mistake tells you where to begin.')+`<section class="panel"><h2>Try before you read the explanation.</h2>${DIAGNOSTIC.map(q=>choices(q)).join('')}${confidence('diagnosticConfidence')}<div class="actions"><button data-action="diagnostic">Check my starting point</button></div><div id="diagnostic-feedback" class="feedback" role="status">${state.diagnostic?diagnosticFeedback():''}</div></section><section class="panel"><span class="badge">TARGETED BRIDGE · ABOUT 20 MINUTES</span><h2 style="margin-top:15px">A percentage is a change relative to a starting value.</h2><p>If £200 becomes £210, the change is £10. Divide by £200: 10 ÷ 200 = 0.05, or 5%. A pound change and a percentage change are different measurements.</p><p>For a portfolio, a <strong>weight</strong> is the fraction of money in an investment. If 25% of your money earns 8% and 75% earns 0%, the whole portfolio earns 0.25 × 8% + 0.75 × 0% = 2%.</p><p><strong>Try a new case:</strong> £400 grows to £420. Enter the percentage increase as a number, without the % symbol.</p>${field('bridgeAnswer','Percentage increase','','number')}<div class="actions"><button class="secondary" data-action="bridge">Check calculation</button></div><div id="bridge-feedback" class="feedback" role="status"></div><details class="hint"><summary>Hint ladder</summary><p>1. Subtract the starting value from the ending value.</p><p>2. Divide that change by £400.</p><p>3. Multiply the decimal by 100 to express a percentage.</p></details></section><section class="panel"><span class="badge">EXTENSION IF YOU GOT 3/3</span><h2 style="margin-top:15px">The same change, a different base.</h2><p>An investment falls from £100 to £80, then rises back to £100. Calculate each percentage change. Explain why adding the two percentages gives a misleading account of the round trip. Use your own workings, then check the explanation.</p>${field('extensionReason','Your workings and explanation','A fall of … followed by a rise of …','textarea')}<details class="hint"><summary>Compare with an explanation after trying</summary><p>The fall is 20%. The rise is 25% because £80 is now the base. The final value equals the original value: the compound return is 0%. This extension is optional and ungraded.</p></details></section><p class="mini">Pacing: 5 minutes to attempt, 20 for the bridge or extension, 5 to correct and reflect. Take more time if needed; the chapter has no timer.</p>`;},
markets(){return heading('STEP 03 · 35 MINUTES','What do you<br>actually own?','Start with the economic claim. A familiar product name can hide important differences in ownership, repayment and risk.')+`<div class="table-wrap"><table><caption>Four building blocks</caption><thead><tr><th>Instrument</th><th>Your claim</th><th>One risk to remember</th></tr></thead><tbody><tr><td><strong>Cash deposit</strong></td><td>A balance at a bank, under its account terms.</td><td>Inflation can reduce purchasing power. Access, bank risk and deposit protection depend on the account and jurisdiction.</td></tr><tr><td><strong>Bond</strong></td><td>You lend to an issuer, usually for promised interest and repayment.</td><td>Default is possible. Market prices can fall when interest rates rise.</td></tr><tr><td><strong>Share</strong></td><td>A part ownership stake in a business.</td><td>Neither dividends nor a positive resale price is guaranteed.</td></tr><tr><td><strong>Fund / ETF</strong></td><td>An interest in a pooled vehicle holding other investments. An ETF trades on an exchange.</td><td>Risk comes from the holdings, concentration, fees and structure. “Fund” does not mean safe.</td></tr></tbody></table></div><div class="callout"><strong>A market is a way to exchange claims.</strong><p>Prices reflect what buyers and sellers are willing to trade at a point in time. A quoted price is not a promise about the future. Your research question concerns evidence, rather than a guaranteed forecast.</p></div><section class="panel"><h2>Worked example: a bond fund is not one bond.</h2><p>A single bond may promise repayment on a date, subject to default. A bond fund owns a portfolio that changes over time; its units generally have no equivalent fixed redemption value on your chosen date. Both involve debt exposure, but the wrapper changes what you own.</p><p><strong>Predict:</strong> would buying three funds necessarily give more diversification than buying one? Pause and name what you would need to inspect.</p><details class="hint"><summary>Compare your reasoning</summary><p>You need to inspect the underlying holdings and exposures. Three funds may own the same companies or share the same sector risk. The number of product labels is not enough.</p></details></section><section class="panel"><h2>Your turn: classify the claim.</h2><p>Choose the most specific description. You can revise after seeing the feedback; all four must be correct to complete this practice.</p>${INSTRUMENTS.map(q=>`<label class="field" for="instrument-${q.id}">${q.name}</label><select id="instrument-${q.id}" data-save><option value="">Choose an instrument</option>${[['cash','Cash deposit'],['bond','Bond'],['share','Share'],['fund','Fund / ETF']].map(([v,l])=>`<option value="${v}" ${val('instrument-'+q.id)===v?'selected':''}>${l}</option>`).join('')}</select>`).join('')}<div class="actions"><button data-action="classify">Check my classifications</button></div><div id="classification-feedback" class="feedback" role="status">${state.classification?classificationFeedback():''}</div></section><section class="panel"><h2>Transfer: explain it to someone else.</h2><p>A friend says, “My technology ETF owns 30 businesses, so it cannot lose much.” Write a two-sentence response. Include the distinction between a vehicle and its holdings, and one shared exposure. Compare with the checklist below and improve one sentence.</p>${field('marketTransfer','Your response','The ETF is … Its holdings may …','textarea')}<details class="hint"><summary>Self-check after writing</summary><p>A complete response explains that the ETF is a pooled vehicle, that the holdings may share technology-sector risks, and that diversification cannot guarantee against loss. Do not promise a particular amount of loss or protection.</p></details></section><p class="mini">Suggested pacing: 10 minutes reading, 5 predicting, 10 classifying and correcting, 10 for the transfer explanation.</p>`;},
case(){return heading('STEP 04 · 25 MINUTES','Compared<br>with what?','A benchmark is a declared baseline. Choose it because it fits the question—not because it makes your result look good.')+`<section class="panel"><span class="badge">WORKED CASE · HYPOTHETICAL</span><h2 style="margin-top:15px">Maya tests a cautious allocation.</h2><p>Maya asks: “In these supplied one-year scenarios, does a 50% cash / 40% bond / 10% share allocation lose less in stress than a 20% cash / 40% bond / 40% share baseline, and what return does it give up in the steady scenario?” This is a scenario comparison, not proof of a superior investment strategy.</p><p>Both start with £1,000. We apply one full-year return to each starting holding and do not rebalance within the year. Cash, bonds and shares here are invented teaching assets. Trading costs, fees and taxes are set to zero for this first illustration; future chapters introduce them.</p><div class="table-wrap"><table><caption>Invented one-year total returns; not market observations</caption><thead><tr><th>Asset</th><th>Steady scenario</th><th>Stress scenario</th></tr></thead><tbody><tr><td>Cash</td><td>+2%</td><td>+1%</td></tr><tr><td>Bonds</td><td>+3%</td><td>−5%</td></tr><tr><td>Shares</td><td>+8%</td><td>−20%</td></tr></tbody></table></div><h3>The benchmark in the steady scenario</h3><p>20% × 2% + 40% × 3% + 40% × 8% = <strong>4.8%</strong>. Ending value = £1,000 × 1.048 = <strong>£1,048</strong>. Here the percentages used as weights are decimals: 0.20, 0.40 and 0.40.</p><h3>Maya's allocation in the same scenario</h3><p>50% × 2% + 40% × 3% + 10% × 8% = <strong>3.0%</strong>. Ending value = <strong>£1,030</strong>. That is 1.8 <strong>percentage points</strong> below the benchmark, not a £1.80 difference. The pound difference is £18.</p><div class="callout"><strong>What would make the comparison unfair?</strong><p>Using different dates, different starting amounts without normalising returns, silently changing costs, or choosing a favourable benchmark after seeing the result. In later strategy work we also need matching intended exposures. Maya is deliberately comparing two different allocations to describe a trade-off, so their risk difference is part of her question.</p></div></section><section class="panel"><h2>Finish the example before opening the answer.</h2><p>Use the stress returns to calculate both allocations. Predict which will lose less, then calculate how many percentage points separate them.</p>${field('casePrediction','Your prediction and reasoning','I expect … because …','textarea')}${field('caseGap','Difference in stress losses, in percentage points (positive number)','','number')}<div class="actions"><button data-action="case-check">Check the completed example</button></div><div id="case-feedback" class="feedback" role="status">${state.done.case?'Worked case completed. Your answer and explanation are saved.':''}</div><details class="hint"><summary>Need a hint?</summary><p>Calculate 0.20 × 1 + 0.40 × (−5) + 0.40 × (−20) for the baseline. Then repeat with 0.50, 0.40 and 0.10. Keep negative signs until you have calculated both totals.</p></details></section><section class="panel"><h2>What makes a useful research question?</h2><div class="timeline"><div><strong>Rule or comparison</strong><p>What exactly will you do or compare?</p></div><div><strong>Benchmark</strong><p>What declared baseline answers the question fairly?</p></div><div><strong>Period and evidence</strong><p>Which dates or scenarios, and which quantity will you measure?</p></div><div><strong>Limits</strong><p>What assumptions could make your conclusion fail elsewhere?</p></div></div><p>“What is the best investment?” leaves these decisions hidden. “Does rule A reduce maximum drawdown against its matching baseline over the supplied period, after declared costs?” specifies evidence. <strong>Maximum drawdown</strong> means the largest fall from a previous portfolio-value peak; you will calculate it in a later chapter.</p></section>`;},
lab(){return heading('STEP 05 · 35 MINUTES','Make a prediction.<br>Then test it.','Change the allocation, not the past. Compare two supplied scenarios and record what would make you revise your idea.')+`<div class="callout"><strong>A small, transparent model</strong><p>Invented one-year asset returns: steady = cash +2%, bonds +3%, shares +8%; stress = cash +1%, bonds −5%, shares −20%. Start with £1,000, buy once at the start, and hold. No within-year rebalancing. Fees, trading costs and taxes are zero. The same assumptions apply to the fixed 20 / 40 / 40 benchmark.</p></div><section class="panel"><h2>1. Predict before you run.</h2>${field('labPrediction','What do you expect, and why?','For example: Increasing cash may … because …','textarea')}${confidence('labConfidence')}<h2 style="margin-top:28px">2. Choose starting weights.</h2><p class="mini">Use numbers from 0 to 100. The three weights must total 100%. Nothing here selects an optimal or personally suitable portfolio.</p><div class="allocation">${[['weightCash','Cash',20],['weightBond','Bonds',40],['weightShare','Shares',40]].map(([id,l,d])=>`<label class="field" for="${id}">${l} (%)<input id="${id}" data-save type="number" min="0" max="100" step="any" value="${esc(val(id)===''?d:val(id))}"></label>`).join('')}</div><label class="field" for="regime">Scenario</label><select id="regime" data-save><option value="steady" ${val('regime')!=='stress'?'selected':''}>Steady year</option><option value="stress" ${val('regime')==='stress'?'selected':''}>Stress year</option></select><div class="actions"><button data-action="run">Run my comparison ↗</button><button class="secondary" data-action="baseline">Reset weights to benchmark</button></div><div id="lab-feedback" class="feedback" role="status"></div><div id="lab-result">${state.labRuns.length?labResult(state.labRuns.at(-1)):''}</div></section><section class="panel"><h2>3. Check one result by hand.</h2><p>Enter the ending portfolio value for your latest run, in pounds. Use £1,000 × (1 + portfolio return ÷ 100). Check using your weights and the asset returns rather than copying the displayed total.</p>${field('handCheck','Ending value (£), without the currency symbol','','number')}<div class="actions"><button class="secondary" data-action="hand-check">Check my arithmetic</button></div><div id="hand-feedback" class="feedback" role="status">${state.fields.handVerified?'A hand calculation was verified for your latest run.':''}</div><details class="hint"><summary>Show the calculation method</summary><p>Convert each weight to a decimal, multiply by its asset return, and add the contributions. A 50 / 40 / 10 stress portfolio returns 0.50 × 1 + 0.40 × (−5) + 0.10 × (−20) = −3.5%. It ends at £965.</p></details><h2 style="margin-top:25px">4. Change the scenario and critique.</h2><p>Run the <strong>same non-benchmark allocation</strong> in both scenarios. This isolates the scenario change. Then explain the trade-off and a limitation. Your first two runs are evidence, not a search for the most attractive result.</p>${field('labReflection','What happened to your prediction?','Compare both scenarios. What changed, and why might real markets differ?','textarea')}<div class="actions"><button data-action="complete-lab">Save my lab reflection</button><button class="secondary" data-action="download-csv">Download all runs (CSV)</button></div><div id="lab-completion" class="feedback" role="status">${state.done.lab?'Lab completed: paired scenarios, a hand check and a reflection are saved.':''}</div></section><section class="panel"><h2>Your experiment log</h2><p class="mini">Every run is retained on this device. The export records all runs, not just favourable results. Resetting weights does not clear the log.</p><div class="table-wrap">${runTable()}</div></section><p class="mini">Suggested pacing: 5 minutes to predict, 15 to run and hand-check, 10 to compare scenarios, 5 to revise your explanation.</p>`;},
assessment(){const qs=currentAssessment(state),attempt=state.assessmentAttempts.at(-1),set=Number(val('assessmentSet')||0),visible=attempt&&attempt.set===set;return heading('STEP 06 · 25 MINUTES','Try a<br>different case.','Retrieve the ideas before reopening the lessons. Then use the feedback to revise your reasoning.')+`<div class="callout"><strong>How the check works</strong><p>Six questions, no time limit. Complete at least 5 correctly, including the fair-benchmark and evidence-limit questions (3 and 6). Attempts and corrections stay in your export. You may use a calculator. Confidence is ungraded. A pass records formative completion, not professional competence.</p></div><section class="panel"><h2>Independent check · case ${set%2===0?'A':'B'}</h2><p class="mini">The following cases use new numbers and examples. ${state.assessmentAttempts.length} submitted attempt${state.assessmentAttempts.length===1?'':'s'} so far.</p>${qs.map((q,i)=>choices({...q,title:`${i+1}. ${q.title}`},'quiz-')).join('')}${confidence('assessmentConfidence')}<div class="actions"><button data-action="grade">Check my answers</button><button class="secondary" data-action="new-case">Switch to ${set%2===0?'case B':'case A'}</button></div><div id="assessment-feedback" class="feedback" role="status">${visible?assessmentFeedback(attempt):''}</div></section><section class="panel"><h2>Make feedback change your next action.</h2><p>After checking, return to one relevant example. Write what changed in your reasoning, then correct the answer and resubmit. If you passed on the first try, identify an assumption or a tempting wrong answer and explain why it matters. Switching cases clears the answer fields for the new attempt; previous attempts remain in the log. There are two cases, so later switches repeat a case.</p>${field('assessmentRevision','My correction or reflection','I first thought … The evidence or definition shows … Next time I will …','textarea')}<div class="actions"><button data-action="save-revision">Save my feedback response</button></div><div id="revision-feedback" class="feedback" role="status">${state.fields.revisionSaved?'Feedback response saved.':''}</div></section>`;},
finish(){return heading('STEP 07 · 15 MINUTES','Leave with a<br>research question.','Bring the pieces together in a research card you can take into the next chapter. A clear question is already progress.')+`<section class="panel"><span class="badge">YOUR RESEARCH CARD</span><h2 style="margin-top:15px">Specify the evidence before you see it.</h2><p>This card evaluates the classroom allocation comparison, not a live investment choice. Use a non-benchmark allocation you tested. Free-text reasoning is self-reviewed here; the app checks completeness and arithmetic, not the validity of your research claim.</p>${field('planRule','1. Rule / allocation','For example: Buy 50% cash, 40% bonds and 10% shares at the start; hold for the year.','textarea')}${field('planBenchmark','2. Benchmark and why it fits','State the fixed 20 / 40 / 40 classroom baseline and the trade-off it helps examine.','textarea')}${field('planEvidence','3. Period and measurable evidence','Use both supplied one-year scenarios. State the return or ending-value comparison you will report.','textarea')}${field('planLimits','4. A limit and what would change your mind','Name a zero-cost or synthetic-data assumption, and a result that would weaken your claim.','textarea')}<h3 style="margin-top:22px">Self-review against the criteria</h3><div class="options">${savedCheck('planC1','I named a reproducible allocation and the baseline, rather than asking for the “best investment”.')}${savedCheck('planC2','I stated the same scenarios, starting value and cost conventions for both comparisons.')}${savedCheck('planC3','I will report the unfavourable result too, and I stated a limitation.')}</div><details class="hint"><summary>Compare with an exemplar after drafting</summary><p>“I will compare buy-and-hold 50 / 40 / 10 with the fixed 20 / 40 / 40 baseline, starting each at £1,000 in both invented one-year scenarios. I will report each total return and the percentage-point difference. I expect smaller stress losses but lower steady returns. Real costs or different asset returns could change the result. These two toy scenarios do not establish future performance.”</p><p>A strong response specifies the comparison, reports both results and limits its claim. A claim that the allocation must outperform in real markets needs revision.</p></details>${field('planRevision','What did you change after the criteria or exemplar?','Describe one specific edit and why it makes the question more testable.','textarea')}<div class="actions"><button data-action="save-plan">Save my research card</button><button class="secondary" data-action="export">Export progress & research card ↗</button></div><div id="plan-feedback" class="feedback" role="status">${state.plan?'Research card saved. You can revise and save again.':''}</div></section><section class="panel"><h2>Check your chapter evidence.</h2>${STEPS.map(([id,title])=>`<div class="status-row"><a href="#${id}">${title}</a><span>${state.done[id]?'✓ Complete':'To finish'}</span></div>`).join('')}<div class="callout"><strong>${chapterComplete(state)?'Chapter complete. Your next step is financial mathematics.':'You can revisit any unfinished step.'}</strong><p>${chapterComplete(state)?'You have a market map, a scenario log, an independent check and a research card. Export your work before moving to another device. <a href="chapter-02/">Continue to Chapter 2: financial mathematics →</a>':'Completion needs the specified evidence, not time spent on a page. Saving your card does not automatically pass the independent check.'}</p></div></section><details class="hint"><summary>Glossary and reading</summary><p><strong>Benchmark:</strong> the declared baseline for a comparison. <strong>Allocation:</strong> how money is divided among holdings. <strong>Return:</strong> gain or loss relative to a starting value. <strong>Percentage point:</strong> a difference between percentages. <strong>Synthetic:</strong> invented for a stated purpose. <strong>Maximum drawdown:</strong> largest fall from a previous value peak.</p><ul class="source-links"><li><a href="https://www.investor.gov/introduction-investing/investing-basics/investment-products">Investor.gov: investment products</a></li><li><a href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation">Investor.gov: asset allocation and diversification</a></li><li><a href="https://www.investor.gov/introduction-investing/getting-started/understanding-fees">Investor.gov: fees</a></li></ul><p class="mini">Optional external reading is not required for completion. External sites have their own privacy policies. <a href="chapter-guide.html">Printable text lesson and equivalent exercises</a>.</p></details>`;}
};

function diagnosticFeedback(){return `<strong>${state.diagnostic.score}/3 · ungraded starting-point check</strong><ul>${DIAGNOSTIC.map(q=>`<li>${esc(q.feedback[state.diagnostic.answers[q.id]])}</li>`).join('')}</ul><p>${state.diagnostic.score===3?'Try the extension; the bridge remains available if useful.':'Work through the bridge, then check the new calculation. Revisit any explanation you need.'}</p>`;}
function classificationFeedback(){return `<strong>${state.classification.score}/4 correct.</strong><ul>${INSTRUMENTS.map(q=>`<li>${state.classification.answers[q.id]===q.answer?'✓ '+q.explanation:'Revisit “'+q.name+'”: '+q.hint}</li>`).join('')}</ul><p>${state.classification.score===4?'Now explain the ETF claim in the transfer task.':'Change the relevant choices and check again. No penalty for revising practice.'}</p>`;}
function labResult(r){return `<h3 style="margin-top:25px">Run ${state.labRuns.indexOf(r)+1} · ${r.regime==='stress'?'stress':'steady'} scenario</h3><div class="bars" aria-hidden="true"><span class="bar-cash" style="width:${r.weights[0]}%"></span><span class="bar-bond" style="width:${r.weights[1]}%"></span><span class="bar-share" style="width:${r.weights[2]}%"></span></div><div class="legend"><span style="--c:#d7dfa0">Cash ${r.weights[0]}%</span><span style="--c:#6e9679">Bonds ${r.weights[1]}%</span><span style="--c:#204e41">Shares ${r.weights[2]}%</span></div><div class="metrics"><div class="metric"><span>Your portfolio return</span><strong>${r.gross.toFixed(2)}%</strong></div><div class="metric"><span>Ending value from £1,000</span><strong>${money(r.ending)}</strong></div><div class="metric"><span>Difference from baseline</span><strong>${(r.gross-r.benchmark).toFixed(2)} pp</strong></div></div><p class="mini">Baseline return: ${r.benchmark.toFixed(2)}%. Percentage-point difference = your return − baseline return. The allocation strip above is also labelled in text. No real market data or fees are included.</p>`;}
function runTable(){return state.labRuns.length?`<table><caption>All hypothetical runs; baseline is 20% cash / 40% bonds / 40% shares</caption><thead><tr><th>Run</th><th>Scenario</th><th>Cash / bond / share weights</th><th>Return</th><th>Ending value</th><th>Baseline return</th></tr></thead><tbody>${state.labRuns.map((r,i)=>`<tr><td>${i+1}</td><td>${r.regime}</td><td>${r.weights.join(' / ')}%</td><td>${r.gross.toFixed(2)}%</td><td>${money(r.ending)}</td><td>${r.benchmark.toFixed(2)}%</td></tr>`).join('')}</tbody></table>`:'<p class="empty">No runs yet. Make a prediction, then run a comparison.</p>';}
function assessmentFeedback(a){const qs=a.questions;return `<strong>${a.score}/${a.total} · ${a.passed?'Numerical check passed':'Keep practising'}</strong><p>${a.passed?'Save a feedback response below to finish this step.':'You need 5/6 and correct answers to questions 3 and 6. Read the reasons, revise, and resubmit.'}</p><ol>${qs.map((q,i)=>`<li><strong>${a.details[i].correct?'Correct':'Revisit'}:</strong> ${esc(q.why)}</li>`).join('')}</ol>`;}
function exportProgress(){const payload={chapter:'Quant Finance Foundations · Chapter 01',version:VERSION,exportedAt:new Date().toISOString(),...state,completion:chapterComplete(state),notice:'Formative self-study record. Free-text responses are self-reviewed. No credential or verified proficiency is conferred.'};download('qf-chapter-01-progress.json',JSON.stringify(payload,null,2),'application/json');announce('Progress file downloaded. It includes your saved answers and all submitted attempts.');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function render(focus=true){const target=location.hash.slice(1);if(target==='lesson'){ $('#lesson').focus();return;}page=STEPS.some(([id])=>id===target)?target:(STEPS.some(([id])=>id===state.lastPage)?state.lastPage:'start');state.lastPage=page;$('#lesson').innerHTML=views[page]()+pythonLink(1,page)+bottom();persist();document.title=`${STEPS.find(([id])=>id===page)[1]} · Quant Finance Studio`;if(focus){$('#lesson').focus();window.scrollTo({top:0,behavior:'instant'});}}

document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-save]'))return;const id=el.name||el.id;state.fields[id]=el.type==='checkbox'?el.checked:el.value;const feedbackId=invalidateEvidence(state,id);if(feedbackId&&$('#'+feedbackId))$('#'+feedbackId).textContent='Work changed. Check or save this step again when ready.';persist();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
if(action==='begin'){$('#setup-panel').scrollIntoView({behavior:'instant',block:'start'});$('#workspace').focus();}
if(action==='export')exportProgress();
if(action==='setup'){if(!val('setupConfirmed'))return feedback('setup-feedback','Check the setup confirmation once you can enter text and locate the export and reset controls.',true);mark('start');go('readiness');}
if(action==='diagnostic'){const answers=Object.fromEntries(DIAGNOSTIC.map(q=>[q.id,val(q.id)===''?null:Number(val(q.id))]));if(Object.values(answers).some(v=>v===null))return feedback('diagnostic-feedback','Please choose one answer for each starting-point question. This is ungraded.',true);state.diagnostic={answers,score:DIAGNOSTIC.filter(q=>answers[q.id]===q.answer).length};mark('readiness');feedback('diagnostic-feedback',diagnosticFeedback());}
if(action==='bridge'){const n=Number(val('bridgeAnswer'));feedback('bridge-feedback',val('bridgeAnswer')!==''&&Math.abs(n-5)<.001?'Correct: (420 − 400) ÷ 400 × 100 = 5%. Try explaining why the starting value is the denominator.':'First find the £20 change, then divide by the £400 starting value and multiply by 100. Enter the result as a percentage number.',!(val('bridgeAnswer')!==''&&Math.abs(n-5)<.001));}
if(action==='classify'){const answers=Object.fromEntries(INSTRUMENTS.map(q=>[q.id,val('instrument-'+q.id)]));if(Object.values(answers).some(v=>!v))return feedback('classification-feedback','Choose a description for all four claims, then check.',true);state.classification={answers,score:INSTRUMENTS.filter(q=>answers[q.id]===q.answer).length};if(state.classification.score===4)mark('markets');else persist();feedback('classification-feedback',classificationFeedback());}
if(action==='case-check'){const correct=val('caseGap')!==''&&Math.abs(Number(val('caseGap'))-6.3)<.01;if(!val('casePrediction').trim())return feedback('case-feedback','Write your prediction and a reason first. Then calculate the gap.',true);if(!correct)return feedback('case-feedback','The benchmark returns −9.8%; Maya’s allocation returns −3.5%. Subtract the two returns and enter the positive gap in percentage points. Keep percentage points separate from pounds.',true);mark('case');feedback('case-feedback','Correct: the stress gap is 6.3 percentage points. Maya loses £35 rather than £98, but earns £18 less in the steady scenario. This is a trade-off in two invented scenarios, not evidence of guaranteed superiority.');}
if(action==='baseline'){for(const [id,n] of [['weightCash',20],['weightBond',40],['weightShare',40]])state.fields[id]=String(n);persist();render(false);$('#weightCash').focus();announce('Weights reset to 20% cash, 40% bonds and 40% shares. Your experiment log is retained.');}
if(action==='run'){if(!val('labPrediction').trim())return feedback('lab-feedback','Write a prediction before running the model. A short statement and a reason are enough.',true);try{const weights=['weightCash','weightBond','weightShare'].map(id=>$('#'+id).value);const result=allocate(weights,$('#regime').value);state.labRuns.push({...result,prediction:val('labPrediction'),timestamp:new Date().toISOString()});state.fields.handVerified=false;state.fields.handCheck='';delete state.done.lab;persist();render(false);feedback('lab-feedback',`Run ${state.labRuns.length} recorded. Read the result below, then check it by hand.`);}catch(err){feedback('lab-feedback',esc(err.message),true);}}
if(action==='hand-check'){const r=state.labRuns.at(-1);if(!r)return feedback('hand-feedback','Run a comparison first so there is a result to check.',true);const correct=val('handCheck')!==''&&Math.abs(Number(val('handCheck'))-r.ending)<.011;if(!correct)return feedback('hand-feedback','Use the weights and returns from your latest run. Add the weighted returns, divide the percentage by 100, add 1, and multiply by £1,000. Round pounds to two decimal places.',true);state.fields.handVerified=true;persist();feedback('hand-feedback','Your arithmetic matches the latest run. Explain the weighted calculation in your reflection; matching a number alone does not establish a good research claim.');}
if(action==='complete-lab'){const paired=state.labRuns.some(a=>a.weights.some((v,i)=>Math.abs(v-[20,40,40][i])>.001)&&state.labRuns.some(b=>b.regime!==a.regime&&b.weights.every((v,i)=>Math.abs(v-a.weights[i])<.001)));if(!paired)return feedback('lab-completion','Run the same non-benchmark weights in both steady and stress scenarios. This compares the scenario change while keeping the allocation fixed.',true);if(!state.fields.handVerified)return feedback('lab-completion','Check the ending value for your latest run by hand before completing the lab.',true);if(val('labReflection').trim().length<30)return feedback('lab-completion','Add a reflection of at least 30 characters comparing both scenarios and stating a limitation. Length checks completeness only; use the worked-case reasoning to self-review.',true);mark('lab');feedback('lab-completion','Lab evidence saved: paired scenarios, hand arithmetic and your reflection. Revisit your prediction and make one specific correction if needed.');}
if(action==='download-csv'){if(!state.labRuns.length)return feedback('lab-completion','Run a comparison before downloading its data.',true);download('qf-chapter-01-runs.csv','run,scenario,cash_weight_pct,bond_weight_pct,share_weight_pct,return_pct,ending_gbp,benchmark_return_pct,fee_gbp\n'+state.labRuns.map((r,i)=>[i+1,r.regime,...r.weights,r.gross.toFixed(6),r.ending.toFixed(2),r.benchmark,0].join(',')).join('\n'),'text/csv');announce('All experiment runs downloaded as CSV.');}
if(action==='grade'){const questions=currentAssessment(state);const answers=Object.fromEntries(questions.map(q=>[q.id,val('quiz-'+q.id)===''?null:Number(val('quiz-'+q.id))]));if(Object.values(answers).some(v=>v===null))return feedback('assessment-feedback','Answer all six questions before checking. There is no time limit.',true);const result=gradeQuestions(questions,answers);state.assessmentAttempts.push({...result,answers,questions,set:Number(val('assessmentSet')||0),timestamp:new Date().toISOString()});state.fields.assessmentDirty=false;state.fields.revisionSaved=false;delete state.done.assessment;persist();feedback('assessment-feedback',assessmentFeedback(state.assessmentAttempts.at(-1)),!result.passed);}
if(action==='new-case'){state.fields.assessmentSet=String(Number(val('assessmentSet')||0)+1);for(let i=1;i<=6;i++)state.fields['quiz-a'+i]='';state.fields.assessmentRevision='';state.fields.revisionSaved=false;delete state.done.assessment;persist();render();announce('A different case is ready. Earlier attempts remain in your export.');}
if(action==='save-revision'){const a=state.assessmentAttempts.at(-1);if(!a||a.set!==Number(val('assessmentSet')||0)||state.fields.assessmentDirty)return feedback('revision-feedback','Submit your current answers for this case before responding to its feedback.',true);if(val('assessmentRevision').trim().length<30)return feedback('revision-feedback','Describe a specific correction or reflection in at least 30 characters. Explain what changed and why.',true);state.fields.revisionSaved=true;a.revision=val('assessmentRevision');if(a.passed)mark('assessment');else persist();feedback('revision-feedback',a.passed?'Feedback response saved. The independent check is complete.':'Response saved. Correct the questions and resubmit to reach the pass criteria.');}
if(action==='save-plan'){const ids=['planRule','planBenchmark','planEvidence','planLimits','planRevision'];if(ids.some(id=>val(id).trim().length<20))return feedback('plan-feedback','Complete each of the five text fields with at least 20 characters, including your revision. These are completeness checks; use the criteria to review the quality.',true);if(!['planC1','planC2','planC3'].every(id=>val(id)===true))return feedback('plan-feedback','Review the three criteria and confirm each one, revising your card if necessary.',true);state.plan=Object.fromEntries(ids.map(id=>[id,val(id)]));mark('finish');render(false);feedback('plan-feedback',chapterComplete(state)?'Chapter complete. Your research card and learning evidence are saved on this device. Export a copy for your records.':'Research card saved. The checklist below shows which other evidence is still needed.');}
});
$('#export-sidebar').addEventListener('click',exportProgress);
$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());
$('#close-privacy').addEventListener('click',()=>$('#privacy-dialog').close());
$('#reset-progress').addEventListener('click',()=>{if(!confirm('Delete this chapter’s saved answers, attempts and progress from this browser? Exported files will remain.'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();persist();location.hash='start';render();announce('Chapter progress reset on this device.');});
window.addEventListener('hashchange',()=>render());
render(false);
